package com.villaserena.api.piso;
import java.util.*;
import java.time.*;
import java.math.BigDecimal;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.access.prepost.PreAuthorize;
import com.villaserena.api.auth.UsuarioActual;
import com.villaserena.api.comun.ApiException;
import com.villaserena.api.reservas.IdempotenciaReservas;
import tools.jackson.databind.ObjectMapper;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
@RestController @RequestMapping("/api/v1/laboral")
@PreAuthorize("hasAnyRole('ADMIN','RECEPCION','ROOM_SERVICE','MANTENIMIENTO_LIMPIEZA')")
public class LaboralController {
 private final JdbcTemplate jdbc;private final ObjectMapper json;private final IdempotenciaReservas requests;
 public LaboralController(JdbcTemplate jdbc,ObjectMapper json,IdempotenciaReservas requests){this.jdbc=jdbc;this.json=json;this.requests=requests;}
 public record Solicitud(@NotNull UUID clave,@NotNull Map<String,Object> datos){}
 private ApiException invalid(String s){return ApiException.datosInvalidos(s,List.of());}
 private String text(Map<String,Object>d,String k,int max){Object v=d.get(k);if(!(v instanceof String s)||s.isBlank()||s.length()>max)throw invalid("Revisa "+k+".");return s.trim();}
 private long number(Map<String,Object>d,String k){try{long n=new BigDecimal(String.valueOf(d.get(k))).longValueExact();if(n<0)throw invalid("Revisa "+k+".");return n;}catch(IllegalArgumentException|ArithmeticException e){throw invalid("Revisa "+k+".");}}
 private LocalDate date(String s){try{return LocalDate.parse(s);}catch(Exception e){throw invalid("Fecha inválida.");}}
 private void periodo(LocalDate a,LocalDate b){if(b.isBefore(a)||java.time.temporal.ChronoUnit.DAYS.between(a,b)>366)throw invalid("Selecciona hasta 367 días.");}
 private Map<String,Object> empleado(long id,boolean lock){var rows=jdbc.queryForList("SELECT id,full_name AS nombre,email AS \"correo\",phone AS \"telefono\",role AS \"rol\",area,status AS \"estado\",profile::text AS perfil,version  FROM employees WHERE id=?"+(lock?" FOR UPDATE":""),id);if(rows.isEmpty())throw ApiException.noEncontrado();var r=rows.getFirst();r.put("perfil",json.readValue((String)r.get("perfil"),Map.class));return r;}
 private void audit(String entidad,Object id,Object old,Object next){jdbc.update("INSERT INTO staff_audit(entity,record,employee_id,previous,new) VALUES(?,?,?,?::jsonb,?::jsonb)",entidad,id.toString(),UsuarioActual.id(),old==null?null:json.writeValueAsString(old),json.writeValueAsString(next));}
 private Map<?,?> execute(String scope,Solicitud s,java.util.function.Supplier<Map<?,?>> fn){if(json.writeValueAsString(s.datos()).length()>16000)throw invalid("Solicitud demasiado grande.");return requests.ejecutar("laboral:"+UsuarioActual.id()+":"+scope,s.clave().toString(),s,Map.class,()->(Map)fn.get());}
 @GetMapping("/perfil") public Map<String,Object> perfil(){return empleado(UsuarioActual.id(),false);}
 @GetMapping("/asistencia") public List<Map<String,Object>> propia(@RequestParam LocalDate desde,@RequestParam LocalDate hasta){periodo(desde,hasta);return jdbc.queryForList("SELECT id,date AS \"fecha\",shift AS \"turno\",status AS \"estado\",observation AS \"observacion\",version  FROM staff_attendance WHERE employee_id=? AND date BETWEEN ? AND ? ORDER BY date",UsuarioActual.id(),desde,hasta);}
 @GetMapping("/admin/asistencia") @PreAuthorize("hasRole('ADMIN')") public List<Map<String,Object>> asistencias(@RequestParam LocalDate desde,@RequestParam LocalDate hasta){periodo(desde,hasta);return jdbc.queryForList("SELECT a.id,a.employee_id AS \"empleado_id\",a.date AS \"fecha\",a.shift AS \"turno\",a.status AS \"estado\",a.observation AS \"observacion\",a.version,e.full_name AS nombre  FROM staff_attendance a JOIN employees e ON e.id=a.employee_id WHERE date BETWEEN ? AND ? ORDER BY date,e.full_name",desde,hasta);}
 @PostMapping("/admin/asistencia") @PreAuthorize("hasRole('ADMIN')") public Map<?,?> asistencia(@Valid @RequestBody Solicitud s){return execute("asistencia",s,()->{var d=s.datos();long id=number(d,"empleadoId"),v=number(d,"version");LocalDate fecha=date(text(d,"fecha",10));var emp=empleado(id,true);if(!"ACTIVO".equals(emp.get("estado")))throw invalid("Selecciona un empleado activo.");String estado=text(d,"estado",15),turno=text(d,"turno",60);if(!Set.of("presente","ausente","descanso","pendiente").contains(estado))throw invalid("Estado de asistencia inválido.");if(fecha.isAfter(LocalDate.now(ZoneId.of("America/Guatemala")))&&Set.of("presente","ausente").contains(estado))throw invalid("No registres asistencia cumplida para una fecha futura.");String obs=Objects.toString(d.get("observacion"),"").trim();if(obs.length()>500)throw invalid("Observación demasiado larga.");var rows=jdbc.queryForList("SELECT id,employee_id AS \"empleado_id\",date AS \"fecha\",shift AS \"turno\",status AS \"estado\",observation AS \"observacion\",version FROM staff_attendance WHERE employee_id=? AND date=? FOR UPDATE",id,fecha);Map<String,Object> old=rows.isEmpty()?null:rows.getFirst();long actual=old==null?0:((Number)old.get("version")).longValue();if(v!=actual)throw ApiException.conflicto("VERSION_CAMBIADA","La asistencia cambió. Actualiza antes de guardar.");Long key;if(old==null)key=jdbc.queryForObject("INSERT INTO staff_attendance(employee_id,date,shift,status,observation) VALUES(?,?,?,?,?) RETURNING id",Long.class,id,fecha,turno,estado,obs);else{key=((Number)old.get("id")).longValue();jdbc.update("UPDATE staff_attendance SET shift=?,status=?,observation=?,version=version+1 WHERE id=?",turno,estado,obs,key);}var result=jdbc.queryForMap("SELECT id,employee_id AS \"empleado_id\",date AS \"fecha\",shift AS \"turno\",status AS \"estado\",observation AS \"observacion\",version FROM staff_attendance WHERE id=?",key);audit("asistencia",key,old,result);return result;});}
 @GetMapping("/correcciones") public List<Map<String,Object>> correcciones(){return jdbc.queryForList("SELECT id,employee_id AS \"empleado_id\",field AS \"campo\",previous AS \"anterior\",new AS \"nuevo\",reason AS \"motivo\",status AS \"estado\",created_at AS \"creada_en\",resolved_at AS \"resuelta_en\",resolved_by AS \"resuelta_por\",response AS \"respuesta\",version FROM staff_corrections WHERE employee_id=? ORDER BY id DESC",UsuarioActual.id());}
 @GetMapping("/admin/correcciones") @PreAuthorize("hasRole('ADMIN')") public List<Map<String,Object>> solicitudes(){return jdbc.queryForList("SELECT c.id,c.employee_id AS \"empleado_id\",c.field AS \"campo\",c.previous AS \"anterior\",c.new AS \"nuevo\",c.reason AS \"motivo\",c.status AS \"estado\",c.created_at AS \"creada_en\",c.resolved_at AS \"resuelta_en\",c.resolved_by AS \"resuelta_por\",c.response AS \"respuesta\",c.version,e.full_name AS nombre  FROM staff_corrections c JOIN employees e ON e.id=c.employee_id ORDER BY c.id DESC");}
 @PostMapping("/correcciones") public Map<?,?> solicitar(@Valid @RequestBody Solicitud s){return execute("correccion",s,()->{var emp=empleado(UsuarioActual.id(),true);String campo=text(s.datos(),"campo",20),nuevo=text(s.datos(),"nuevo",150),motivo=text(s.datos(),"motivo",500);if(!Set.of("nombre","telefono","correo").contains(campo))throw invalid("Dato no permitido.");if(campo.equals("correo")){nuevo=nuevo.toLowerCase(Locale.ROOT);if(!nuevo.matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"))throw invalid("Correo inválido.");}if(campo.equals("telefono")&&!ValidacionesPersona.telefono(nuevo))throw invalid("Teléfono inválido: usa de 7 a 15 dígitos y prefijo internacional opcional.");String anterior=Objects.toString(emp.get(campo),"");if(anterior.equals(nuevo))throw invalid("El dato nuevo es igual al actual.");if(jdbc.queryForObject("SELECT count(*)  FROM staff_corrections WHERE employee_id=? AND field=? AND status='pendiente'",Integer.class,UsuarioActual.id(),campo)>0)throw ApiException.conflicto("CORRECCION_PENDIENTE","Ya hay una solicitud pendiente para ese dato.");long id=jdbc.queryForObject("INSERT INTO staff_corrections(employee_id,field,previous,new,reason) VALUES(?,?,?,?,?) RETURNING id",Long.class,UsuarioActual.id(),campo,anterior,nuevo,motivo);var r=jdbc.queryForMap("SELECT id,employee_id AS \"empleado_id\",field AS \"campo\",previous AS \"anterior\",new AS \"nuevo\",reason AS \"motivo\",status AS \"estado\",created_at AS \"creada_en\",resolved_at AS \"resuelta_en\",resolved_by AS \"resuelta_por\",response AS \"respuesta\",version FROM staff_corrections WHERE id=?",id);audit("correccion",id,null,r);return r;});}
 @PostMapping("/admin/correcciones/{id}") @PreAuthorize("hasRole('ADMIN')") public Map<?,?> resolver(@PathVariable long id,@Valid @RequestBody Solicitud s){return execute("resolver:"+id,s,()->{var rows=jdbc.queryForList("SELECT id,employee_id AS \"empleado_id\",field AS \"campo\",previous AS \"anterior\",new AS \"nuevo\",reason AS \"motivo\",status AS \"estado\",created_at AS \"creada_en\",resolved_at AS \"resuelta_en\",resolved_by AS \"resuelta_por\",response AS \"respuesta\",version FROM staff_corrections WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw ApiException.noEncontrado();var old=rows.getFirst();if(!old.get("estado").equals("pendiente")||((Number)old.get("version")).longValue()!=number(s.datos(),"version"))throw ApiException.conflicto("VERSION_CAMBIADA","La solicitud ya cambió.");String estado=text(s.datos(),"estado",15),respuesta=text(s.datos(),"respuesta",500);if(!Set.of("aprobada","rechazada").contains(estado))throw invalid("Selecciona aprobar o rechazar.");long empId=((Number)old.get("empleado_id")).longValue();if(empId==UsuarioActual.id())throw invalid("Otra persona administradora debe resolver tu solicitud.");var emp=empleado(empId,true);String campo=old.get("campo").toString();if(estado.equals("aprobada")){if(!Objects.toString(emp.get(campo),"").equals(old.get("anterior")))throw ApiException.conflicto("DATO_CAMBIADO","El dato fue modificado; revisa la solicitud antes de aprobar.");String columna=switch(campo){case "nombre"->"full_name";case "telefono"->"phone";case "correo"->"email";default->throw invalid("Dato no permitido.");};if(campo.equals("correo")&&jdbc.queryForObject("SELECT count(*)  FROM employees WHERE lower(email)=lower(?) AND id<>?",Integer.class,old.get("nuevo"),empId)>0)throw ApiException.conflicto("CORREO_EXISTENTE","El correo ya está asociado a otra cuenta.");jdbc.update("UPDATE employees SET "+columna+"=?,version=version+1 WHERE id=?",old.get("nuevo"),empId);audit("perfil",empId,emp,empleado(empId,false));}jdbc.update("UPDATE staff_corrections SET status=?,response=?,resolved_by=?,resolved_at=now(),version=version+1 WHERE id=?",estado,respuesta,UsuarioActual.id(),id);var result=jdbc.queryForMap("SELECT id,employee_id AS \"empleado_id\",field AS \"campo\",previous AS \"anterior\",new AS \"nuevo\",reason AS \"motivo\",status AS \"estado\",created_at AS \"creada_en\",resolved_at AS \"resuelta_en\",resolved_by AS \"resuelta_por\",response AS \"respuesta\",version FROM staff_corrections WHERE id=?",id);audit("correccion",id,old,result);return result;});}
 @GetMapping("/admin/nominas") @PreAuthorize("hasRole('ADMIN')") public List<Map<String,Object>> nominas(@RequestParam String periodo){LocalDate month=mes(periodo);return jdbc.queryForList("SELECT id,period AS \"periodo\",employee_id AS \"empleado_id\",name AS \"nombre\",base,bonuses AS \"bonos\",deductions AS \"descuentos\",net AS \"neto\",created_at AS \"creada_en\",created_by AS \"creada_por\", 'CALCULADA' AS estado  FROM staff_payroll WHERE period=? ORDER BY name,id",month);}
 @GetMapping("/nominas") public List<Map<String,Object>> propiaNomina(){return jdbc.queryForList("SELECT id,period AS \"periodo\",name AS \"nombre\",base,bonuses AS \"bonos\",deductions AS \"descuentos\",net AS \"neto\",created_at AS \"creada_en\",'CALCULADA' AS estado  FROM staff_payroll WHERE employee_id=? ORDER BY period DESC,id DESC",UsuarioActual.id());}
 private LocalDate mes(String s){try{return YearMonth.parse(s).atDay(1);}catch(Exception e){throw invalid("Período mensual inválido.");}}
 private BigDecimal importe(Map<?,?>p,String k,boolean requerido){Object value=p.get(k);if(value==null&&!requerido)return BigDecimal.ZERO;if(value==null)throw invalid("Falta el salario base en el perfil laboral.");try{var n=new BigDecimal(value.toString());if(n.signum()<0||n.scale()>2||n.compareTo(new BigDecimal("9999999"))>0)throw invalid("Importe laboral inválido.");return n;}catch(NumberFormatException e){throw invalid("Importe laboral inválido.");}}
 @PostMapping("/admin/nominas") @PreAuthorize("hasRole('ADMIN')") public Map<?,?> calcular(@Valid @RequestBody Solicitud s){return execute("nomina",s,()->{LocalDate month=mes(text(s.datos(),"periodo",7));Object values=s.datos().get("empleados");if(!(values instanceof List<?> list)||list.isEmpty()||list.size()>200)throw invalid("Selecciona empleados para calcular.");var ids=new TreeSet<Long>();for(Object value:list){try{ids.add(Long.parseLong(value.toString()));}catch(Exception e){throw invalid("Empleado inválido.");}}if(ids.size()!=list.size())throw invalid("No repitas empleados.");var results=new ArrayList<Map<String,Object>>();for(long id:ids){var emp=empleado(id,true);if(!emp.get("estado").equals("ACTIVO"))throw invalid("Selecciona empleados activos.");if(jdbc.queryForObject("SELECT count(*)  FROM staff_payroll WHERE period=? AND employee_id=?",Integer.class,month,id)>0)throw ApiException.conflicto("NOMINA_EXISTENTE","Ya hay una nómina conservada de ese empleado para el período.");var p=(Map<?,?>)emp.get("perfil");BigDecimal base=importe(p,"salarioBase",true),bonos=importe(p,"bonosExtras",false),descuentos=importe(p,"descuentosNomina",false),neto=base.add(bonos).subtract(descuentos);if(neto.signum()<0)throw invalid("Los descuentos superan el importe calculado.");long key=jdbc.queryForObject("INSERT INTO staff_payroll(period,employee_id,name,base,bonuses,deductions,net,created_by) VALUES(?,?,?,?,?,?,?,?) RETURNING id",Long.class,month,id,emp.get("nombre"),base,bonos,descuentos,neto,UsuarioActual.id());var result=jdbc.queryForMap("SELECT id,period AS \"periodo\",employee_id AS \"empleado_id\",name AS \"nombre\",base,bonuses AS \"bonos\",deductions AS \"descuentos\",net AS \"neto\",created_at AS \"creada_en\",created_by AS \"creada_por\" FROM staff_payroll WHERE id=?",key);audit("nomina",key,null,result);results.add(result);}return Map.of("registros",results,"estado","CALCULADA");});}
}
